import * as T from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {RanchRenderer} from './ranch-renderer.js';
import {HEX_RADIUS,cellWorld,cardKey,instanceCells,inspectConnections} from './playground-model.js';
const S=.1;
export function createPlaygroundRenderer(host,onSelect){
 const scene=new T.Scene();scene.background=new T.Color('#e5e7da');const renderer=new RanchRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));host.append(renderer.domElement);
 const camera=new T.PerspectiveCamera(38,1,.1,1200),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=false;controls.maxPolarAngle=Math.PI*.47;controls.minDistance=6;controls.maxDistance=400;
 scene.add(new T.HemisphereLight('#fff6df','#728779',1.15));const sun=new T.DirectionalLight('#fff0d2',2);sun.position.set(-20,45,20);scene.add(sun);
 let root=new T.Group(),labels=[],anchors=[],generation=0,currentBoard=null,playing=false;scene.add(root);const layer=document.createElement('div');layer.id='pg-labels';host.append(layer);const templateCache=new Map();
 const material=(color,role='plain')=>{const m=new T.MeshLambertMaterial({color:color||'#b4bc91'});m.userData.storyKind=role;return m;};
 function render(){renderer.render(scene,camera);for(const a of anchors){const v=a.position.clone().project(camera);a.label.hidden=v.z>1||Math.abs(v.x)>1||Math.abs(v.y)>1;a.label.style.left=(v.x+1)*host.clientWidth/2+'px';a.label.style.top=(1-v.y)*host.clientHeight/2+'px';}window.RanchView?.changed();}
 controls.addEventListener('change',render);
 function fit(){const box=new T.Box3().setFromObject(root),center=box.isEmpty()?new T.Vector3():box.getCenter(new T.Vector3()),size=box.isEmpty()?new T.Vector3(20,1,20):box.getSize(new T.Vector3()),radius=Math.max(10,size.length()/2),angle=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*camera.aspect)),distance=radius/Math.sin(angle)*1.12;controls.target.copy(center);camera.position.copy(center).add(new T.Vector3(1,1.1,1.35).normalize().multiplyScalar(distance));controls.update();render();}
 new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();fit();}).observe(host);
 function geometry(data){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(data.positions,3));if(data.normals?.length===data.positions.length)g.setAttribute('normal',new T.Float32BufferAttribute(data.normals,3));else g.computeVertexNormals();if(data.indices)g.setIndex(data.indices);return g;}
 async function asset(path){if(!path.startsWith('/')||path.includes('..'))throw Error('Invalid saved asset path');if(!templateCache.has(path))templateCache.set(path,(async()=>{const response=await fetch(path);if(!response.ok)throw Error('Saved asset unavailable: '+path);const data=await response.json(),g=new T.Group();for(const part of data){const color=Array.isArray(part.color)?new T.Color().setRGB(...part.color,T.SRGBColorSpace):part.color;g.add(new T.Mesh(geometry(part),material(color,part.role)));}return g;})());return (await templateCache.get(path)).clone(true);}
 async function rendition(card){const r=card.rendition;if(r.scene?.object)return new T.ObjectLoader().parse(r.scene);const g=new T.Group();
  if(!Array.isArray(r.meshes)&&!Array.isArray(r.assets))throw Error('Unsupported saved rendition format for '+card.id);
  for(const data of r.meshes||[]){const m=new T.Mesh(geometry(data),material(Array.isArray(data.color)?new T.Color().setRGB(...data.color):data.color,data.role));if(data.position)m.position.fromArray(data.position);if(data.rotation)m.rotation.fromArray(data.rotation);if(data.scale)m.scale.fromArray(data.scale);g.add(m);}
  for(const data of r.assets||[]){const m=await asset(data.path);if(data.position)m.position.fromArray(data.position);if(data.rotation)m.rotation.fromArray(data.rotation);if(data.scale)m.scale.fromArray(data.scale);g.add(m);}return g;
 }
 function hexOutline(c,color,y=0){const center=cellWorld(c),pts=Array.from({length:7},(_,i)=>new T.Vector3((center.x+Math.sin(i*Math.PI/3)*HEX_RADIUS)*S,y,(center.z+Math.cos(i*Math.PI/3)*HEX_RADIUS)*S));return new T.Line(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color,transparent:true,opacity:.6}));}
 async function prepare(board,selected,report){const next=new T.Group(),nextAnchors=[],nextLabels=[];
  for(const instance of board.instances){const card=board.cards[cardKey(instance.cardId,instance.cardRevision)],model=await rendition(card),g=new T.Group(),c=cellWorld(instance);model.scale.multiplyScalar(S);g.add(model);g.position.set(c.x*S,(instance.elevation||0)*S,c.z*S);g.rotation.y=-instance.rotation*Math.PI/3;g.traverse(o=>{o.userData.instanceId=instance.instanceId;});next.add(g);
   for(const cell of instanceCells(instance,card))next.add(hexOutline(cell,instance.instanceId===selected?'#537b45':'#879275',(instance.elevation||0)*S+.04));
   const jobs=report?.lastDay?.jobs?.filter(j=>j.instanceId===instance.instanceId)||[],blocked=report?.warnings?.some(w=>w.instanceIds?.includes(instance.instanceId)),state=blocked?'blocked':jobs.some(j=>j.status==='working')?'working':jobs.some(j=>j.status==='blocked')?'blocked':'idle';
   const label=document.createElement('div');label.className='pg-label';label.dataset.state=state;label.textContent=(card.name||card.id)+' · '+state;label.title=jobs.filter(j=>j.reason).map(j=>j.reason).join('; ');nextLabels.push(label);const box=new T.Box3().setFromObject(g),position=box.isEmpty()?g.position.clone():box.getCenter(new T.Vector3());position.y=(box.isEmpty()?0:box.max.y)+.4;nextAnchors.push({position,label});
  }
  if(!board.instances.length)for(let q=-2;q<=2;q++)for(let r=-2;r<=2;r++)if(Math.abs(q+r)<=2)next.add(hexOutline({q,r},'#b6bea6'));
  for(const edge of inspectConnections(board).connections){const a=edge.access.a,b=edge.access.b,dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz);if(len<.05)continue;const width=1.5,nx=-dz/len*width,nz=dx/len*width,points=[[a.x+nx,a.y+.04,a.z+nz],[a.x-nx,a.y+.04,a.z-nz],[b.x+nx,b.y+.04,b.z+nz],[b.x-nx,b.y+.04,b.z-nz]],geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute([0,1,2,2,1,3].flatMap(i=>points[i].map(v=>v*S)),3));geo.computeVertexNormals();const m=new T.Mesh(geo,new T.MeshBasicMaterial({color:'#c8b88b',side:T.DoubleSide}));next.add(m);}
  return {root:next,anchors:nextAnchors,labels:nextLabels};
 }
 async function update(board,selected,report){const ticket=++generation,next=await prepare(board,selected,report);if(ticket!==generation)return;scene.remove(root);root=next.root;scene.add(root);anchors=next.anchors;labels=next.labels;layer.replaceChildren(...labels);currentBoard=board;render();}
 const ray=new T.Raycaster();let pointer=null;renderer.domElement.addEventListener('pointerdown',e=>pointer={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(!pointer||Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y)>5)return;const rect=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,1-(e.clientY-rect.top)/rect.height*2),camera);const hit=ray.intersectObjects(root.children,true).find(h=>h.object.userData.instanceId);if(hit)onSelect(hit.object.userData.instanceId);});
 let raf;function animate(time){if(!playing)return;for(const a of anchors)if(a.label.dataset.state==='working')a.label.style.opacity=String(.8+.2*Math.sin(time/450));render();raf=requestAnimationFrame(animate);}
 return {update,fit,render,prepare,state:()=>({camera:camera.position.toArray(),target:controls.target.toArray(),instances:currentBoard?.instances.length||0}),setPlaying(value){playing=value&&!matchMedia('(prefers-reduced-motion: reduce)').matches;cancelAnimationFrame(raf);labels.forEach(l=>l.style.opacity='1');if(playing)raf=requestAnimationFrame(animate);}};
}
